import json
from itertools import permutations

def has_direct(a, b, direct_routes):
    return frozenset([a, b]) in direct_routes

def window_length(window):
    start, end = window
    return end - start + 1

def compute_itinerary():
    # Inputs
    total_days = 16
    cities_info = {
        "London": {
            "desired_days": 7,
            "relatives_window": (1, 7)  # inclusive
        },
        "Split": {
            "desired_days": 5,
            "show_window": (7, 11)  # inclusive
        },
        "Oslo": {
            "desired_days": 2
        },
        "Porto": {
            "desired_days": 5
        }
    }
    # Direct flights (undirected)
    direct_flights_raw = {
        ("London", "Oslo"),
        ("Split", "Oslo"),
        ("Oslo", "Porto"),
        ("London", "Split"),
    }
    direct_routes = {frozenset(pair) for pair in direct_flights_raw}

    # Validate anchored windows for London and Split
    london_days = cities_info["London"]["desired_days"]
    london_window = cities_info["London"]["relatives_window"]
    if window_length(london_window) != london_days:
        raise ValueError("London desired days must match the relatives window length.")

    split_days = cities_info["Split"]["desired_days"]
    split_window = cities_info["Split"]["show_window"]
    if window_length(split_window) != split_days:
        raise ValueError("Split desired days must match the show window length.")

    # Ensure direct flight between London and Split to allow overlap on day 7
    if not has_direct("London", "Split", direct_routes):
        raise ValueError("No direct flight between London and Split, cannot satisfy overlap constraint.")

    # Ensure the anchoring windows align to allow day-7 overlap
    if london_window[1] != split_window[0]:
        raise ValueError("London relatives window must end on the same day Split show window begins to allow overlap.")

    # Build initial anchored blocks: London then Split
    blocks = []
    blocks.append({"city": "London", "start": london_window[0], "end": london_window[1]})
    blocks.append({"city": "Split", "start": split_window[0], "end": split_window[1]})

    # Remaining cities to schedule
    remaining_cities = [c for c in cities_info.keys() if c not in ["London", "Split"]]

    # Try to find an order of remaining cities that satisfies direct-flight adjacency
    found = False
    best_blocks = None
    for order in permutations(remaining_cities):
        valid = True
        # Check direct flights from Split to first, and between each subsequent pair
        prev_city = blocks[-1]["city"]
        for city in order:
            if not has_direct(prev_city, city, direct_routes):
                valid = False
                break
            prev_city = city
        if not valid:
            continue

        # Build tentative blocks with overlap on transition days: start_next = end_prev
        temp_blocks = [dict(b) for b in blocks]
        current_end = temp_blocks[-1]["end"]
        for city in order:
            desired = cities_info[city]["desired_days"]
            start = current_end  # overlap on the transition day
            end = start + desired - 1
            temp_blocks.append({"city": city, "start": start, "end": end})
            current_end = end

        # Validate total trip length
        if temp_blocks[-1]["end"] == total_days:
            best_blocks = temp_blocks
            found = True
            break

    if not found:
        raise ValueError("Could not find a valid order of remaining cities that fits all constraints and total days.")

    # Build JSON itinerary output
    itinerary = []
    for b in best_blocks:
        itinerary.append({
            "day_range": f"Day {b['start']}-{b['end']}",
            "place": b["city"]
        })

    return {"itinerary": itinerary}

if __name__ == "__main__":
    result = compute_itinerary()
    print(json.dumps(result, ensure_ascii=False))
